    @classmethod
    def _collect_raw(
        cls,
        state: Mapping[str, Any],
        *,
        boundary: Mapping[str, Any],
        application_build: Mapping[str, Any],
        observed_at: str,
        evaluation_session_id: str,
        udid: str,
    ) -> dict[str, Any]:
        notes = [dict(item) for item in state.get("notes", []) if isinstance(item, Mapping)]
        users = [dict(item) for item in state.get("users", []) if isinstance(item, Mapping)]
        user_state = state.get("userState") if isinstance(state.get("userState"), Mapping) else {}
        lina_state = user_state.get("lina") if isinstance(user_state.get("lina"), Mapping) else {}
        liked = lina_state.get("likedNoteIds") if isinstance(lina_state.get("likedNoteIds"), list) else []
        saved = lina_state.get("savedNoteIds") if isinstance(lina_state.get("savedNoteIds"), list) else []

        selected_notes: dict[str, tuple[list[dict[str, Any]], dict[str, Any]]] = {}
        for group, expected in _NOTE_EXPECTED.items():
            matches = [
                note for note in notes
                if note.get("title") == expected["title"] and note.get("authorHandle") == "lina"
            ]
            selected_notes[group] = (matches, _note_evidence(matches[0] if len(matches) == 1 else None))

        target_matches = [
            note for note in notes
            if note.get("title") == "Friday cushion foundation with one shade too peachy"
        ]
        target = target_matches[0] if len(target_matches) == 1 else {}
        target_id = target.get("id")
        target_evidence = {
            "id": target_id,
            "title": target.get("title"),
            "category": target.get("category"),
            "liked": target_id in liked,
            "saved": target_id in saved,
        }
        lina_matches = [user for user in users if user.get("handle") == "lina"]
        lina = lina_matches[0] if len(lina_matches) == 1 else {}
        profile = {"handle": lina.get("handle"), "title": lina.get("title")}

        events = [dict(item) for item in state.get("evaluationEvents", []) if isinstance(item, Mapping)]
        mode = boundary.get("mode")
        if mode == "automatic_baseline_seq":
            floor = boundary.get("baseline_max_event_seq")
            suffix = [event for event in events if isinstance(event.get("seq"), int) and event.get("seq") > floor]
        else:
            start = _parse_datetime(boundary.get("start"))
            end = _parse_datetime(boundary.get("end"))
            suffix = []
            for event in events:
                try:
                    stamp = _parse_datetime(event.get("timestamp"))
                except ValueError:
                    continue
                if start <= stamp <= end:
                    suffix.append(event)
        suffix.sort(key=lambda event: int(event.get("seq") or 0))

        groups = {
            group: {
                "match_count": len(matches),
                "note": note,
                "application_build": dict(application_build),
            }
            for group, (matches, note) in selected_notes.items()
        }
        groups["beauty_engagement"] = {
            "match_count": len(target_matches),
            "target_note": target_evidence,
        }
        groups["profile_role"] = {
            "match_count": len(lina_matches),
            "profile": profile,
        }
        return {
            "schema_version": "1.0",
            "task_id": TASK_ID,
            "evaluation_session_id": evaluation_session_id,
            "observed_at": observed_at,
            "runtime": {
                "udid": udid,
                "ios_device_profile": IOS_DEVICE_PROFILE,
                "source_simulator_name": SOURCE_SIMULATOR_NAME,
                "bundle_id": DEFAULT_BUNDLE_ID,
                "local_state_key": LOCAL_STATE_KEY,
            },
            "boundary": dict(boundary),
            "groups": groups,
            "event_suffix": suffix,
            "state_summary": {
                "evaluationEventSeq": state.get("evaluationEventSeq"),
                "note_count": len(notes),
            },
            "read_only": True,
        }

